import type { User } from '@/types';

// 解析CSV数据并转换为User类型
export function parseCSVUserData(csvData: string): User[] {
  const lines = csvData.split('\n');
  const headers = lines[0].split(',');
  const users: User[] = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const values = line.split(',');
    if (values.length < headers.length) continue;

    const user: User = {
      id: values[0],
      gender: values[1],
      age: parseInt(values[2]) || 0,
      skinType: values[3],
      isMember: values[4] === '是',
      province: values[10] || '未知',
      rScore: 3, // 默认值
      fScore: 3, // 默认值
      mScore: 3, // 默认值
      userCategory: values[5],
      clusterName: values[6],
      ite: 0.05, // 默认值
      upliftType: values[7] === '敏感型' ? 'sensitive' :
                 values[7] === '自然转化型' ? 'natural' :
                 values[7] === '反作用型' ? 'adverse' : 'sleeping',
      preferredSeries: [values[8]],
      recommendedProduct: values[9] || ''
    };

    users.push(user);
  }

  return users;
}

